<?php /** Schedule administration list. Author: Ong Kar Heng (2408830). */ ?>
<div class="page-heading"><div><h1>Collection schedules</h1><p class="lead">Generate tasks from full bins, unresolved complaints, or a routine route.</p></div><a class="button" href="<?= url('schedule/create') ?>">Generate schedule</a></div>
<form method="get" action="<?= url('schedule') ?>" class="filter-panel filter-compact"><label>Date<input type="date" name="date" value="<?= e($filters['date']) ?>"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach (['Planned','Completed','Cancelled'] as $option): ?><option <?= $filters['status'] === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><button class="button button-secondary" type="submit">Apply</button></form>
<div class="table-scroll"><table class="table"><thead><tr><th>Schedule</th><th>Date/time</th><th>Strategy</th><th>Tasks</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($schedules as $schedule): ?><tr><td>#<?= $schedule->getKey() ?></td><td><?= e($schedule->getDate()) ?><br><?= e($schedule->getTimeSlot()) ?></td><td><?= e($schedule->getStrategy()) ?></td><td><?= count($schedule->getAssignments()) ?></td><td><span class="badge badge-status"><?= e($schedule->getStatus()) ?></span></td><td><a href="<?= url('schedule/show/' . $schedule->getKey()) ?>">View</a></td></tr><?php endforeach; ?><?php if ($schedules === []): ?><tr><td colspan="6" class="empty">No schedules match the filters.</td></tr><?php endif; ?></tbody></table></div>
